CREATE TABLE IF NOT EXISTS assistant_provider (id INT NOT NULL PRIMARY KEY, document TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS assistant_usage (user_id VARCHAR(64) NOT NULL, day VARCHAR(10) NOT NULL, count INT NOT NULL DEFAULT 0, active_until BIGINT NOT NULL DEFAULT 0, request_id VARCHAR(64) NOT NULL DEFAULT '', PRIMARY KEY (user_id, day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
